// ========================================
// POST
// Regla 1: el usuario debe existir y
// estar activo
// ========================================

const crearCuenta = async (
  req,
  res,
  next
) => {

  try {

    const datosPermitidos =
      matchedData(
        req,
        {
          locations: [
            "body"
          ]
        }
      );


    const usuario =
      await usuariosService
        .obtenerUsuarioPorId(
          datosPermitidos.usuarioId
        );


    if (
      !usuario
    ) {

      return res
        .status(400)
        .json({
          mensaje:
            "El usuario indicado no existe"
        });
    }


    if (
      usuario.estado !== "activo"
    ) {

      return res
        .status(409)
        .json({
          mensaje:
            "No se puede crear una cuenta para un usuario inactivo"
        });
    }


    const cuentaCreada =
      await cuentasService
        .crearCuenta(
          datosPermitidos
        );


    res
      .status(201)
      .json({

        mensaje:
          "Cuenta creada correctamente",

        cuenta:
          cuentaCreada
      });

  } catch (error) {
    next(error);
  }
};


// ========================================
// GET /:id/saldo
// Devuelve total, apartado y disponible
// ========================================

const obtenerSaldoCuenta = async (
  req,
  res,
  next
) => {

  try {

    const {
      id
    } = req.params;


    const cuenta =
      await cuentasService
        .obtenerCuentaPorId(
          id
        );


    if (
      !cuenta
    ) {

      return res
        .status(404)
        .json({
          mensaje:
            "Cuenta no encontrada"
        });
    }


    const saldoApartado =
      await cuentasService
        .calcularSaldoApartado(
          id
        );


    const saldoDisponible =
      redondearMoneda(
        cuenta.saldoTotal -
        saldoApartado
      );


    res
      .status(200)
      .json({

        cuentaId:
          cuenta.id,

        saldoTotal:
          cuenta.saldoTotal,

        saldoApartado,

        saldoDisponible,

        moneda:
          cuenta.moneda
      });

  } catch (error) {
    next(error);
  }
};


