// ========================================
// PATCH /:id/estado
// Regla 7: no se puede cerrar una cuenta
// con saldo total mayor que 0
// ========================================

const actualizarEstadoCuenta = async (
  req,
  res,
  next
) => {

  try {

    const {
      id
    } = req.params;


    const datosPermitidos =
      matchedData(
        req,
        {
          locations: [
            "body"
          ]
        }
      );


    const cuentaActual =
      await cuentasService
        .obtenerCuentaPorId(
          id
        );


    if (
      !cuentaActual
    ) {

      return res
        .status(404)
        .json({
          mensaje:
            "Cuenta no encontrada"
        });
    }


    const nuevoEstado =
      datosPermitidos.estado;

    const estadoActual =
      cuentaActual.estado;

    const permitidos =
      transicionesPermitidas[
        estadoActual
      ];


    if (
      !permitidos.includes(
        nuevoEstado
      )
    ) {

      return res
        .status(409)
        .json({
          mensaje:
            `No se permite cambiar una cuenta de ${estadoActual} a ${nuevoEstado}`
        });
    }


    if (
      nuevoEstado === "cerrada" &&
      cuentaActual.saldoTotal > 0
    ) {

      return res
        .status(409)
        .json({
          mensaje:
            "No se puede cerrar una cuenta con saldo total mayor que cero"
        });
    }


    const cuentaActualizada =
      await cuentasService
        .actualizarEstadoCuenta(
          id,
          nuevoEstado
        );


    res
      .status(200)
      .json({

        mensaje:
          "Estado de la cuenta actualizado correctamente",

        cuenta:
          cuentaActualizada
      });

  } catch (error) {
    next(error);
  }
};


module.exports = {
